sp_widget.client_script:
api.controller = function () {
    var c = this;
    c.caseUrl = function (record) {
        return '?id=form&table=' + (record.table || 'x_sln_store_suppli_supply_case') + '&sys_id=' + record.sys_id;
    };
    c.taskUrl = function (record) {
        return '?id=form&table=x_sln_store_suppli_supplier_task&sys_id=' + record.sys_id;
    };
    c.producerUrl = function (sysId) {
        return '?id=sc_cat_item&sys_id=' + sysId;
    };
};

sp_widget.css:
.sss-shell { color: $text-color; padding: 24px 0 48px; }
.sss-shell:focus { outline: none; }
.sss-breadcrumb { align-items: center; display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.sss-breadcrumb a { color: $link-color; text-decoration: underline; }
.sss-hero { background: linear-gradient(125deg, $brand-primary 0%, #002faf 100%); border-radius: 0 $border-radius-large 0 0; box-shadow: 0 8px 24px rgba(0,47,175,.18); color: $btn-primary-color; overflow: hidden; padding: 36px; position: relative; }
.sss-hero:after { background: $brand-warning; bottom: 0; content: ""; height: 8px; left: 0; position: absolute; width: 88px; }
.sss-eyebrow { font-size: 14px; font-weight: 700; letter-spacing: .08em; margin: 0; text-transform: uppercase; }
.sss-hero h1 { color: $btn-primary-color; font-size: 36px; line-height: 1.08; margin: 10px 0 12px; max-width: 720px; }
.sss-welcome { font-size: 18px; line-height: 1.5; margin: 0; max-width: 760px; }
.sss-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
.sss-actions .btn { border-radius: 999px; padding: 10px 18px; }
.sss-primary, .sss-primary:hover, .sss-primary:focus { background: $btn-primary-color; color: #002faf; border: 2px solid $btn-primary-color; font-weight: 700; }
.sss-secondary, .sss-secondary:hover, .sss-secondary:focus { background: transparent; color: $btn-primary-color; border: 2px solid $btn-primary-color; font-weight: 700; }
.sss-summary { display: grid; gap: 16px; grid-template-columns: repeat(3, minmax(0, 1fr)); margin-top: 24px; }
.sss-summary__item { background: $panel-bg; border: 1px solid $gray-lighter; border-left: 6px solid $brand-primary; display: flex; flex-direction: column; min-height: 108px; padding: 20px; }
.sss-summary__item strong { color: #002faf; font-size: 30px; line-height: 1; }
.sss-summary__item span { color: $text-color; margin-top: 10px; }
.sss-panel { background: $panel-bg; border: 1px solid $gray-lighter; border-radius: 0 $border-radius-large 0 0; padding: 24px; margin-top: 24px; }
.sss-panel h2 { color: #002faf; margin-top: 0; }
.sss-panel h2:after { background: $brand-warning; content: ""; display: block; height: 5px; margin-top: 10px; width: 48px; }
.sss-panel .table > thead > tr > th { border-bottom: 2px solid #002faf; color: #000000; }
.sss-panel .table > tbody > tr:nth-child(even) { background: #f7f7f7; }
.sss-list { list-style: none; margin: 0; padding: 0; }
.sss-list li { display: flex; justify-content: space-between; gap: 16px; padding: 12px 0; border-bottom: 1px solid $gray-lighter; }
.sss-list a, .sss-panel a { color: $link-color; text-decoration: underline; }
.sss-list a:focus, .sss-panel a:focus, .sss-actions a:focus { outline: 3px solid $brand-warning; outline-offset: 3px; }
.sss-status { background: #e6eeff; border: 1px solid #89b7fd; border-radius: 999px; color: #00206f; display: inline-block; font-size: 13px; font-weight: 700; padding: 3px 9px; white-space: nowrap; }
@media (max-width: 767px) { .sss-hero { padding: 26px 22px; } .sss-hero h1 { font-size: 30px; } .sss-welcome { font-size: 16px; } .sss-summary { grid-template-columns: 1fr; } .sss-list li { display: block; } .sss-list .sss-status { margin-top: 8px; } }

sp_widget.script:
(function () {
    data.audience = options.audience || (gs.hasRole('x_sln_store_suppli.supplier_agent') ? 'supplier' : 'internal');
    data.userName = gs.getUserDisplayName();
    data.cases = [];
    data.tasks = [];
    data.knowledge = [];

    function producer(name) {
        var item = new GlideRecord('sc_cat_item_producer');
        item.addQuery('name', name);
        item.addQuery('active', true);
        item.setLimit(1);
        item.query();
        return item.next() ? item.getUniqueValue() : '';
    }

    data.requestProducer = producer('Submit Store Supply Request');
    data.issueProducer = producer('Report Store Supply Issue');

    var cases = new GlideRecord('x_sln_store_suppli_supply_case');
    cases.addQuery('supply_state', 'NOT IN', 'closed,cancelled');
    cases.orderByDesc('sys_updated_on');
    cases.setLimit(20);
    cases.query();
    while (cases.next()) {
        if (!cases.canRead()) continue;
        data.cases.push({
            sys_id: cases.getUniqueValue(),
            table: cases.getValue('sys_class_name'),
            number: cases.getDisplayValue('number'),
            short_description: cases.getDisplayValue('short_description'),
            store: cases.getDisplayValue('store'),
            state: cases.getDisplayValue('supply_state'),
            priority: cases.getDisplayValue('priority'),
            updated: cases.getDisplayValue('sys_updated_on'),
        });
    }

    if (data.audience === 'supplier') {
        var tasks = new GlideRecord('x_sln_store_suppli_supplier_task');
        tasks.addQuery('released', true);
        tasks.addQuery('task_state', 'NOT IN', 'complete,cancelled');
        tasks.orderByDesc('sys_updated_on');
        tasks.setLimit(20);
        tasks.query();
        while (tasks.next()) {
            if (!tasks.canRead()) continue;
            data.tasks.push({
                sys_id: tasks.getUniqueValue(),
                number: tasks.getDisplayValue('number'),
                short_description: tasks.getDisplayValue('short_description'),
                state: tasks.getDisplayValue('task_state'),
                released: tasks.getDisplayValue('released_on'),
            });
        }
    }

    var knowledge = new GlideRecord('kb_knowledge');
    knowledge.addQuery('workflow_state', 'published');
    knowledge.addQuery('short_description', 'LIKE', 'supply');
    knowledge.orderByDesc('sys_view_count');
    knowledge.setLimit(5);
    knowledge.query();
    while (knowledge.next()) {
        if (!knowledge.canRead()) continue;
        data.knowledge.push({ sys_id: knowledge.getUniqueValue(), number: knowledge.getDisplayValue('number'), title: knowledge.getDisplayValue('short_description') });
    }
})();
